BEGIN;
CREATE TABLE IF NOT EXISTS marketing_channel_templates(id SERIAL PRIMARY KEY,channel VARCHAR(20) NOT NULL CHECK(channel IN('whatsapp','sms')),name VARCHAR(160) NOT NULL,provider_template_id VARCHAR(160),content TEXT,approval_status VARCHAR(30) NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS marketing_channel_policies(id SERIAL PRIMARY KEY,channel VARCHAR(20) UNIQUE NOT NULL,email_daily INTEGER DEFAULT 3,email_weekly INTEGER DEFAULT 10,daily_limit INTEGER DEFAULT 3,quiet_start TIME,quiet_end TIME,timezone VARCHAR(80) DEFAULT 'UTC',settings JSONB NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS marketing_outbound_audit(id BIGSERIAL PRIMARY KEY,marketing_contact_id INTEGER REFERENCES marketing_contacts(id) ON DELETE SET NULL,channel VARCHAR(20) NOT NULL,action_type VARCHAR(50) NOT NULL,template_id INTEGER REFERENCES marketing_channel_templates(id) ON DELETE SET NULL,status VARCHAR(20) NOT NULL,blocked_reason VARCHAR(120),provider_message_id VARCHAR(255),details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS marketing_crm_handoff_requests(id BIGSERIAL PRIMARY KEY,marketing_contact_id INTEGER NOT NULL REFERENCES marketing_contacts(id) ON DELETE RESTRICT,handoff_type VARCHAR(40) NOT NULL,payload JSONB NOT NULL DEFAULT '{}',status VARCHAR(20) NOT NULL DEFAULT 'queued',idempotency_key VARCHAR(180) UNIQUE NOT NULL,last_error VARCHAR(500),created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW());
COMMIT;
